  "facts": [
    {
      "fact_text": {
        "text": "The IDE provides a context‑menu item called “Open in Terminal” (on macOS) or “Open in Command Prompt” (on Windows) to open the current project folder in a terminal window.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The Java compiler is invoked with the command `javac` followed by the source‑file name (e.g., `javac Main.java`).",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "On macOS and Linux the filename must match the exact case of the class name because those operating systems are case‑sensitive.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Compiling a Java source file produces a `.class` file that contains the bytecode representation of the program.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The generated `.class` file is stored in the project’s output folder (e.g., `out/production/<project‑name>/...`).",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Java bytecode is platform‑independent; it can run on any operating system that has a Java Runtime Environment (JRE).",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The Java Virtual Machine (JVM) translates Java bytecode into native code for the underlying operating system at runtime.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Because of this architecture, Java applications are portable across Windows, macOS, Linux, and other platforms that provide a JVM.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Compile and run a Java program from the terminal",
        "refs": ["Q0000", "Q0001", "Q0005"]
      },
      "prerequisites": null,
      "steps": [
        {
          "text": "Open a terminal window for the project folder using the IDE’s “Open in Terminal” (macOS) or “Open in Command Prompt” (Windows) menu item.",
          "refs": ["Q0000"]
        },
        {
          "text": "Navigate to the folder containing the Java source file if not already there.",
          "refs": []
        },
        {
          "text": "Invoke the Java compiler with `javac Main.java` (replace `Main.java` with the actual source filename).",
          "refs": ["Q0001"]
        },
        {
          "text": "Locate the generated `Main.class` file in the project’s output directory (e.g., `out/production/...`).",
          "refs": ["Q0002"]
        },
        {
          "text": "Run the program with the Java Virtual Machine using `java Main`.",
          "refs": ["Q0005"]
        }
      ],
      "outcomes": null,
      "content": {
        "text": "These steps compile Java source code into platform‑independent bytecode and then execute it via the JVM.",
        "refs": ["Q0003", "Q0004"]
      }
    }
  ],
